# Solve Sudoku with given fixed cells
import itertools

# Fixed cells
fixed = {
    2: 3,
    11: 6,
    13: 8,
    20: 9,
    22: 2,
    35: 7,
    42: 2,
    46: 9,
    50: 4,
    57: 6,
    58: 4,
    60: 9,
    62: 8,
    69: 5,
    78: 6,
    79: 4
}

# Convert to grid
grid = [[0]*9 for _ in range(9)]
for idx, val in fixed.items():
    r, c = divmod(idx, 9)
    grid[r][c] = val

print("Initial grid:")
for row in grid:
    print(row)

# Solve using backtracking
def solve_sudoku(board):
    # Find empty cell
    for i in range(9):
        for j in range(9):
            if board[i][j] == 0:
                # Try digits
                for num in range(1, 10):
                    if is_valid(board, i, j, num):
                        board[i][j] = num
                        if solve_sudoku(board):
                            return True
                        board[i][j] = 0
                return False
    return True

def is_valid(board, row, col, num):
    # Check row
    for j in range(9):
        if board[row][j] == num:
            return False
    # Check column
    for i in range(9):
        if board[i][col] == num:
            return False
    # Check 3x3 block
    br = (row // 3) * 3
    bc = (col // 3) * 3
    for i in range(br, br+3):
        for j in range(bc, bc+3):
            if board[i][j] == num:
                return False
    return True

# Make a copy
import copy
board = copy.deepcopy(grid)
if solve_sudoku(board):
    print("Solved:")
    for row in board:
        print(row)
    # Flatten
    flat = [board[i][j] for i in range(9) for j in range(9)]
    print("Flat:", flat)
else:
    print("UNSAT")

# Verify solution
flat = [1, 2, 3, 4, 5, 6, 7, 8, 9, 4, 5, 6, 7, 8, 9, 1, 2, 3, 7, 8, 9, 1, 2, 3, 4, 5, 6, 2, 1, 4, 3, 6, 5, 8, 9, 7, 3, 6, 5, 8, 9, 7, 2, 1, 4, 8, 9, 7, 2, 1, 4, 3, 6, 5, 5, 3, 1, 6, 4, 2, 9, 7, 8, 6, 4, 2, 9, 7, 8, 5, 3, 1, 9, 7, 8, 5, 3, 1, 6, 4, 2]

# Check rows
for i in range(9):
    row = flat[i*9:(i+1)*9]
    assert sorted(row) == list(range(1,10)), f"Row {i} invalid: {row}"

# Check columns
for j in range(9):
    col = [flat[i*9+j] for i in range(9)]
    assert sorted(col) == list(range(1,10)), f"Col {j} invalid: {col}"

# Check blocks
for br in range(3):
    for bc in range(3):
        block = []
        for i in range(3):
            for j in range(3):
                block.append(flat[(br*3+i)*9 + (bc*3+j)])
        assert sorted(block) == list(range(1,10)), f"Block ({br},{bc}) invalid: {block}"

# Check fixed cells
fixed = {2:3, 11:6, 13:8, 20:9, 22:2, 35:7, 42:2, 46:9, 50:4, 57:6, 58:4, 60:9, 62:8, 69:5, 78:6, 79:4}
for idx, val in fixed.items():
    assert flat[idx] == val, f"Fixed cell {idx} expected {val} got {flat[idx]}"

print("All checks passed!")
